CREATE FUNCTION public.create_engineering_project(_vessel text,_vessel_type text,_class_society text,_flag text,_length_m numeric,_lead_engineer text,_organization_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE org_id uuid;project_id uuid;BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required';END IF;org_id=_organization_id;IF org_id IS NULL THEN SELECT default_organization_id INTO org_id FROM public.profiles WHERE id=auth.uid();END IF;INSERT INTO public.projects(user_id,organization_id,vessel,vessel_type,class_society,flag,length_m,lead_engineer,name) VALUES(auth.uid(),org_id,_vessel,_vessel_type,_class_society,_flag,_length_m,_lead_engineer,_vessel || ' design') RETURNING id INTO project_id;RETURN project_id;END $$;
REVOKE ALL ON FUNCTION public.create_engineering_project(text,text,text,text,numeric,text,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_engineering_project(text,text,text,text,numeric,text,uuid) TO authenticated;
CREATE FUNCTION public.reset_assessment_compliance() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE aid uuid;BEGIN IF TG_OP='DELETE' THEN aid=OLD.assessment_id;ELSE aid=NEW.assessment_id;END IF;UPDATE public.compliance_assessments SET overall_status='REQUIRES_REVIEW',status=CASE WHEN status='completed' THEN 'requires_review' ELSE status END WHERE id=aid AND overall_status='COMPLIANT';IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.reset_assessment_compliance() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER findings_reset_compliance AFTER INSERT OR UPDATE OR DELETE ON public.compliance_findings FOR EACH ROW EXECUTE FUNCTION public.reset_assessment_compliance();
CREATE TRIGGER evidence_reset_compliance AFTER INSERT OR UPDATE OR DELETE ON public.assessment_evidence FOR EACH ROW EXECUTE FUNCTION public.reset_assessment_compliance();
CREATE FUNCTION public.record_review_decision() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.compliance_findings SET review_status=CASE NEW.decision WHEN 'accept' THEN 'accepted' WHEN 'override' THEN 'overridden' ELSE 'open' END WHERE id=NEW.finding_id AND assessment_id=NEW.assessment_id AND project_id=NEW.project_id;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.record_review_decision() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER record_review_decision AFTER INSERT ON public.engineering_reviews FOR EACH ROW EXECUTE FUNCTION public.record_review_decision();
CREATE FUNCTION public.protect_requirement_insert() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NOT EXISTS(SELECT 1 FROM public.regulatory_sources WHERE id=NEW.regulatory_source_id AND status='draft') THEN RAISE EXCEPTION 'Requirements must be authored before publishing the rule-set';END IF;RETURN NEW;END $$;
REVOKE ALL ON FUNCTION public.protect_requirement_insert() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER protect_requirement_insert BEFORE INSERT ON public.regulatory_requirements FOR EACH ROW EXECUTE FUNCTION public.protect_requirement_insert();
COMMENT ON FUNCTION public.create_engineering_project(text,text,text,text,numeric,text,uuid) IS 'Atomic user-scoped creation under caller RLS; no privileged access.';